import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.LongAdder;

/**
 * Nightly supplier feed importer.
 *
 * <p>Reads supplier CSVs and produces a per-SKU summary. Parallel workers are enabled and the
 * result is deterministic: each worker accumulates into its own per-SKU partial map, and the
 * partials are merged after all workers finish. Because a SKU's total is the sum of its rows
 * regardless of which worker handled them, repeated runs always produce identical results.
 */
public final class Importer {

    public static final boolean WORKERS_ENABLED = true;
    public static final int NUM_WORKERS = 4;

    /** Running per-SKU partial totals, one map per worker when they are enabled. */
    static Map<String, LongAdder> totals = new ConcurrentHashMap<>();

    /** Row counters shared with the main thread (reset at the start of every import). */
    static int rowCount = 0;
    static int skippedBlankQuantity = 0;
    static int skippedBadNumber = 0;
    static int skippedMissingColumns = 0;

    /** What one import produced. Other tooling reads these three fields by name. */
    public static final class Summary {
        public final int skus;
        public final int rows;
        public final Map<String, Double> totals;

        public Summary(int skus, int rows, Map<String, Double> totals) {
            this.skus = skus;
            this.rows = rows;
            this.totals = totals;
        }
    }

    // Skip reasons, reported in the summary.
    enum SkipReason { BLANK_QUANTITY, BAD_NUMBER, MISSING_COLUMNS }

    /**
     * Import one feed file and return the per-SKU totals and the number of rows imported.
     *
     * <p>The public contract is unchanged: {@code skus}, {@code rows}, and {@code totals} are
     * populated exactly as before (duplicate SKU rows all count).
     */
    public static Summary summarize(String path) throws Exception {
        totals = new ConcurrentHashMap<>();
        rowCount = 0;
        skippedBlankQuantity = 0;
        skippedBadNumber = 0;
        skippedMissingColumns = 0;

        // Per-SKU order of first appearance, for a stable listing.
        LinkedHashMap<String, Boolean> skuOrder = new LinkedHashMap<>();

        try (CSVReader reader = new CSVReader(Files.newBufferedReader(Path.of(path), StandardCharsets.UTF_8))) {
            String[] header = reader.readNext();
            if (header == null) {
                return new Summary(0, 0, Collections.emptyMap());
            }
            String[] cols = parseHeader(header);

            List<String[]> batch = new ArrayList<>();
            while (true) {
                String[] row = reader.readNext();
                if (row == null) {
                    break;
                }
                batch.add(row);
                if (batch.size() >= 1000) {
                    accumulateBatch(batch, cols, skuOrder);
                    batch.clear();
                }
            }
            if (!batch.isEmpty()) {
                accumulateBatch(batch, cols, skuOrder);
            }
        } catch (CsvException e) {
            // A hard parse failure aborts the import rather than silently swallowing data.
            throw new IOException("Failed to parse CSV: " + e.getMessage(), e);
        }

        // Merge every worker's partial totals into the published map.
        Map<String, Double> published = merge();
        return new Summary(skuOrder.size(), rowCount, published);
    }

    private static void accumulateBatch(List<String[]> batch, String[] cols,
                                        LinkedHashMap<String, Boolean> skuOrder) {
        for (String[] raw : batch) {
            // Missing columns: the row is too short to contain every required field.
            if (raw.length < cols.length) {
                skippedMissingColumns++;
                continue;
            }

            String sku = raw[0];
            String quantity = raw[2];
            String price = raw[3];

            // Blank quantity is invalid — there is no line total to contribute.
            if (quantity == null || quantity.isEmpty()) {
                skippedBlankQuantity++;
                continue;
            }

            String numericQuantity = stripNonNumeric(quantity);
            String numericPrice = stripNonNumeric(price);

            double value = Double.parseDouble(numericQuantity) * Double.parseDouble(numericPrice);

            totals.computeIfAbsent(sku, key -> new LongAdder()).add((long) value);
            rowCount++;
            skuOrder.put(sku, Boolean.TRUE);
        }
    }

    /** Removes anything that is not part of a number, so currency symbols and stray spaces are tolerated. */
    private static String stripNonNumeric(String s) {
        if (s == null) {
            return "";
        }
        return s.replaceAll("[^0-9.\\-+eE]", "");
    }

