    private static String[] parseHeader(String header) {
        List<String[]> rows = new ArrayList<>();
        try (CSVReader reader = new CSVReader(new BufferedReader(new StringReader(header), StandardCharsets.UTF_8))) {
            rows.add(reader.readNext());
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid CSV header: " + header, e);
        }
        String[] first = rows.get(0);
        String[] cols = new String[first.length];
        for (int i = 0; i < cols.length; i++) {
            cols[i] = first[i] == null ? "" : first[i].trim();
        }
        return cols;
    }

    private static Map<String, Double> merge() {
        Map<String, Double> published = new LinkedHashMap<>();
        for (Map.Entry<String, LongAdder> e : totals.entrySet()) {
            published.put(e.getKey(), e.getValue().doubleValue());
        }
        return published;
    }

    public static List<String> skus(Summary summary) {
        return new ArrayList<>(summary.totals.keySet());
    }

