        List<String> keys = skus(result);
        Collections.sort(keys);
        for (String sku : keys) {
            System.out.printf("  %s: %.2f%n", sku, result.totals.get(sku));
        }
    }

    // Kept for compatibility; returns the ordered SKU list.
    static List<String> knownSkus(List<Map<String, String>> rows) {
        List<String> seen = new ArrayList<>();
        for (Map<String, String> r : rows) {
            if (!seen.contains(r.get("sku"))) {
                seen.add(r.get("sku"));
            }
        }
        return seen;
    }
